 38→/** The subpath that serves raw bytes (not the JSON-envelope `files/read`). */
 39→const DOWNLOAD_SUBPATH = "files/download";
 40→
 41→/**
 42→ * Decode the response body to bytes, accepting the shapes an HTTP stub may
 43→ * return: a real Response (or anything with arrayBuffer/text/json), a Buffer,
 44→ * or the already-parsed body.
 45→ *
 46→ * @param {unknown} res
 47→ * @returns {Promise<Buffer>}
 48→ */
 49→async function readBytes(res) {
 50→  if (Buffer.isBuffer(res)) return res;
 51→  if (res instanceof Uint8Array) return Buffer.from(res);
 52→  if (typeof res === "string") return Buffer.from(res, "utf8");
 53→  if (res && typeof res === "object") {
 54→    if (typeof res.arrayBuffer === "function") return Buffer.from(await res.arrayBuffer());
 55→    if (typeof res.text === "function") return Buffer.from(await res.text(), "utf8");
 56→    if (typeof res.json === "function") return Buffer.from(JSON.stringify(await res.json()), "utf8");
 57→    // A stub may hand back the parsed envelope directly.
 58→    return Buffer.from(JSON.stringify(res), "utf8");
 59→  }
 60→  throw new Error("fetchResource: response has no readable body");
 61→}
