 63→/**
 64→ * The bridge's envelope, if this body is one. The discriminant is a numeric
 65→ * `code` together with a `message` or a `data` field — the shape both the
 66→ * bridge and Core write. A raw resource that happens to be JSON without any
 67→ * of that is left as bytes.
 68→ */
 69→function parseEnvelope(bytes) {
 70→  if (bytes.length === 0) return null;
 71→  let parsed;
 72→  try {
 73→    parsed = JSON.parse(bytes.toString("utf8"));
 74→  } catch {
 75→    return null;
 76→  }
 77→  if (!parsed || typeof parsed !== "object" || typeof parsed.code !== "number") return null;
 78→  return typeof parsed.message === "string" || (parsed.data && typeof parsed.data === "object") ? parsed : null;
 79→}
