 88→ */
 89→export async function fetchResource({ skillId, path, bridgeBase, fetcher } = {}) {
 90→  if (!skillId) throw new Error("fetchResource: skillId is required");
 91→  if (!path) throw new Error("fetchResource: path is required");
 92→  if (!bridgeBase) throw new Error("fetchResource: bridgeBase is required");
 93→  const doFetch = fetcher ?? globalThis.fetch;
 94→
 95→  const url = `${String(bridgeBase).replace(/\/+$/, "")}/${DOWNLOAD_SUBPATH}`;
 96→  const res = await doFetch(url, {
 97→    method: "POST",
 98→    headers: { "content-type": "application/json" },
 99→    body: JSON.stringify({ skill_id: skillId, path }),
100→  });
101→
102→  const bytes = await readBytes(res);
103→  const envelope = parseEnvelope(bytes);
104→
105→  if (envelope) {
106→    if (envelope.code !== 0) {
107→      throw new Error(envelope.message ?? `fetchResource: bridge answered code ${envelope.code}`);
108→    }
109→    const data = envelope.data ?? {};
110→    const content = data.content;
111→    if (typeof content !== "string") {
112→      // code 0 but no usable content: the field is missing or the wrong type.
113→      throw new Error(envelope.message ?? "fetchResource: bridge answered code 0 without a string content");
114→    }
115→    return Buffer.from(content, data.encoding === "base64" ? "base64" : "utf8");
116→  }
117→
118→  // No envelope and no 2xx: a transport-level failure whose body is not the
119→  // bridge's own error shape (e.g. an opaque upstream error passed through).
120→  if (res && typeof res === "object" && res.ok === false) {
121→    throw new Error(`fetchResource: HTTP ${res.status ?? "?"} from ${url}`);
122→  }
123→  return bytes;
124→}
