test("render lists changes and unchanged, or says nothing to change", () => {
  const plan = planVisibility({ mode: "reset", baseline, current: { [WRONG]: "team", [RIGHT]: "team", [PEND]: "team" } });
  assert.match(renderPlan(plan), /nothing to change/);
