test("hide mode: named assets private, everything else at baseline, decisions ignored", () => {
  const plan = planVisibility({ mode: "hide", baseline, current: { [WRONG]: "team", [RIGHT]: "team", [PEND]: "team" }, hide: [RIGHT] });
