 * The bridge's envelope, if this body is one. The discriminant is the pair the
 * `envelope()` helper always writes — a numeric `code` and a string `message`;
 * a raw resource that happens to be JSON without both is left as bytes.
 */
function parseEnvelope(bytes) {
  if (bytes.length === 0) return null;
